// List of repositories to monitor
const monitoredRepos = [

  'DaRealBada/sabrowning1-test',
  'DaRealBada/Web-Prog-CW',
  'DaRealBada/Java-OOP-CW',
  'DaRealBada/Python-CW'
];

const webhookData = items[0].json.body;
if (!webhookData || !webhookData.repository) {
  throw new Error("Webhook data is missing repository information.");
}
const triggeringRepo = webhookData.repository.full_name;

const allRepoItems = monitoredRepos.map(repoFullName => {
  const [owner, name] = repoFullName.split('/');
  const isTriggering = repoFullName.toLowerCase() === triggeringRepo.toLowerCase();

  const route = isTriggering ? 'pr_diff_branch' : 'recent_commits_branch';

  return {
    // Everything is placed inside the 'json' object
    json: {
      body: webhookData,
      multi_repo_info: {
        repo_full_name: repoFullName,
        owner: owner,
        name: name,
        is_triggering_repo: isTriggering,
      },
      // The 'route_to' field is now correctly placed HERE
      route_to: route
    }
  };
});

return allRepoItems;

const processedItems = [];

for (const item of items) {
  const webhookData = item.json.body;
  let diffUrl = null;

  // Check for a valid PULL REQUEST with a diff_url
  if (webhookData && webhookData.pull_request && webhookData.pull_request.diff_url) {
    diffUrl = webhookData.pull_request.diff_url;
    console.log(`✅ Found Pull Request diff URL for ${item.json.multi_repo_info.repo_full_name}`);
  }
  // ELSE, check for a PUSH event with a compare URL
  else if (webhookData && webhookData.compare && webhookData.commits?.length > 0) {
    // We can get a machine-readable diff by adding .diff to the compare URL
    diffUrl = webhookData.compare + '.diff';
    console.log(`✅ Found Push compare URL for ${item.json.multi_repo_info.repo_full_name}`);
  }

  // If we found a URL, add it to the item and keep it
  if (diffUrl) {
    item.json.diff_url = diffUrl; // Create a new, standardized property
    processedItems.push(item);
  } else {
    console.log(`❌ No valid diff or compare URL for ${item.json.multi_repo_info.repo_full_name}`);
  }
}

// If no items have a diff, return a placeholder to prevent errors
if (processedItems.length === 0) {
  return [{
    json: {
      no_pr_diff: true, // Kept for consistency
      message: 'No valid pull request or push diffs available for processing',
    }
  }];
}

return processedItems;

// Get the raw diff text from the previous node's output
const diffText = $input.item.json.data;

// Look back to the 'Code2' node to get the repository information
const originalItem = $('Code2').item;
const repoFullName = originalItem.json.body.repository.full_name;

if (!repoFullName) {
  throw new Error("Could not find repository full_name from node 'Code2'.");
}

// This regular expression finds lines that start with '+++ b/' which indicate a file path in a diff
const filePathRegex = /\+\+\+ b\/(.*)/g;
const filePaths = [];
let match;

// Loop through all matches in the diff text
while ((match = filePathRegex.exec(diffText)) !== null) {
  // Ignore special git files like /dev/null
  if (match[1] !== '/dev/null') {
    filePaths.push(match[1]);
  }
}

// Create a new list of items, one for each file that needs to be downloaded
const filesToDownload = filePaths.map(path => {
  return {
    json: {
      // We keep the original diff text for context
      original_diff: diffText,

      // And add the information for the file to be downloaded
      changed_file_path: path,
      file_content_url: `https://api.github.com/repos/${repoFullName}/contents/${path}`
    }
  };
});

return filesToDownload;

const item = $input.item;

// Get the base64 encoded content from the input
const encodedContent = item.json.content;

// Decode it from base64 to a readable string
const decodedContent = Buffer.from(encodedContent, 'base64').toString('utf-8');

// Add the new, decoded field to your data
item.json.file_content = decodedContent;

// Optional: remove the old encoded field to keep the data clean
delete item.json.content;
delete item.json.encoding;

return item;
